    auto const *subReturn = subSign_->ReturnType();
    if (RequiresBridgeConversion(locator_, subReturn, superReturn)) {
        ES2PANDA_ASSERT(subReturn->IsETSObjectType() && subReturn->AsETSObjectType()->IsBoxedPrimitive());
