ir::OpaqueTypeNode *GenericBridgesPhase::AllocOpaqueTypeNode(checker::Type const *type) const noexcept
{
    return Context()->AllocNode<ir::OpaqueTypeNode>(const_cast<checker::Type *>(type), Context()->Allocator());
