class VoidUnionBase {
    m(): string | undefined { throw new Error("base method should not be called") }
}

class VoidUnionDerived extends VoidUnionBase {
    called: boolean = false

    m(): void {
        this.called = true
    }
}

interface VoidUnionInterface {
    m(): string | undefined
}

class VoidUnionImplementation implements VoidUnionInterface {
    called: boolean = false

    m(): void {
        this.called = true
    }
}

function main(): void {
    let ts = new arktest.ArkTestsuite("override_void_return_to_undefined_union")

    ts.addTest("class override returns undefined", () => {
        let derived = new VoidUnionDerived()
        let base: VoidUnionBase = derived
        arktest.assertEQ(base.m(), undefined)
        arktest.assertTrue(derived.called)
    })

    ts.addTest("interface implementation returns undefined", () => {
        let implementation = new VoidUnionImplementation()
        let iface: VoidUnionInterface = implementation
        arktest.assertEQ(iface.m(), undefined)
        arktest.assertTrue(implementation.called)
    })

    ts.run()
}

